{
  "findings": [
    {
      "ref": "[D535]",
      "area": "content",
      "claim": "Roblox has four content maturity labels: Minimal, Mild, Moderate, and Restricted.",
      "stance": "neutral",
      "quote": "For younger users, content maturity labels also work together with Roblox Kids and Roblox Select. These account types help determine what kinds of experiences are available by default based on age, while parents can still use Parental Controls to manage content settings for their family."
    },
    {
      "ref": "[D535]",
      "area": "content",
      "claim": "The Restricted label includes strong violence, heavy realistic blood, romantic themes, unplayable gambling content, alcohol, strong language, social hangouts, private spaces, extended AI interactions, and moderate fear.",
      "stance": "risk",
      "quote": "May contain strong violence, heavy realistic blood, moderate crude humor, romantic themes, unplayable gambling content, the presence of alcohol, strong language, social hangouts and private spaces, extended AI interactions, and/or moderate fear."
    },
    {
      "ref": "[D535]",
      "area": "content",
      "claim": "Restricted experiences are only available to 18+ users who are age checked.",
      "stance": "risk",
      "quote": "These experiences are only available to 18+ users who are age checked."
    },
    {
      "ref": "[D535]",
      "area": "age_gating",
      "claim": "Roblox Kids and Roblox Select use age-based defaults to determine what games are available to younger users.",
      "stance": "mitigation",
      "quote": "Roblox Kids and Roblox Select use age-based defaults to determine what games are available to younger users."
    },
    {
      "ref": "[D535]",
      "area": "age_gating",
      "claim": "Parents with linked accounts can manage content restrictions and may allow or block specific games for their child.",
      "stance": "mitigation",
      "quote": "Parents with linked accounts can still manage content restrictions, and may also be able to allow or block specific games for their child."
    },
    {
      "ref": "[D535]",
      "area": "age_gating",
      "claim": "Access to some content, features, and games may depend on region and account settings.",
      "stance": "neutral",
      "quote": "Access to some content, features, and games may also depend on region and account settings."
    },
    {
      "ref": "[D535]",
      "area": "contact",
      "claim": "Strong language policies apply to both in-experience content and how users communicate within text and voice chat.",
      "stance": "risk",
      "quote": "Strong language policies will apply to both in-experience content and how users communicate within text and voice chat."
    },
    {
      "ref": "[D535]",
      "area": "content",
      "claim": "Content descriptors are determined by the experience creator and may vary between experiences.",
      "stance": "neutral",
      "quote": "Content descriptors are determined by the experience creator and descriptors may vary between experiences."
    }
  ]
}
